/**
 * A value a host already redacted and clipped (apps/mvp decision 0014 §1, step
 * inputs and outputs): JSON text cut at the host's bound, its size before the
 * cut, and whether it was cut. Framework-free, so a terminal reads it the same.
 */
/**
 * The text a value shows: pretty-printed when it parses as JSON and wasn't
 * clipped (a clipped value is a cut string, so it shows as is), else the text.
 */
export const jsonValueText = (value) => {
    if (value.clipped)
        return value.text;
    try {
        const parsed = JSON.parse(value.text);
        return typeof parsed === "string" ? parsed : JSON.stringify(parsed, null, 2);
    }
    catch {
        return value.text;
    }
};
/** A size in bytes as it reads: `512 B`, `1.5 KB`, `16 KB`, `2.3 MB` (1 KB = 1,024 B). */
export const formatBytes = (bytes) => {
    if (!Number.isFinite(bytes) || bytes < 0)
        return "0 B";
    if (bytes < 1024)
        return `${Math.round(bytes)} B`;
    const units = ["KB", "MB", "GB"];
    let size = bytes / 1024;
    let unit = 0;
    while (size >= 1024 && unit < units.length - 1) {
        size /= 1024;
        unit += 1;
    }
    const rounded = size >= 10 ? Math.round(size) : Math.round(size * 10) / 10;
    return `${rounded} ${units[unit]}`;
};
